// src/views/Pulse/usePulseWire.ts
//
// The full-data hook behind The Pulse view. Merges two existing detectors
// into one ranked wire of plain-English WireItems:
//
//   1. Neighborhood VOLUME anomalies  (useAnomalyBaseline + the live 48h window)
//   2. Citywide signals               (useCivicIndicators — trends/tally/milestones)
//
// All prose is generated by the tested pure layer in @/lib/pulse/pulsePhrase.
// This hook only orchestrates: fetch, gate on freshness, rank.
//
// COST NOTE: this loads the full 48h event window (~6000 rows) for the
// per-stream freshness gate (useAnomalyBaseline requires it; its current
// counts are server-side). That's the documented cost of the DEDICATED view
// — Home's teaser must NOT use this hook (it reads the already-cached
// indicators instead). See feedback_frontpage_load_perf.

import { useMemo } from 'react'
import { useCivicIndicators } from '@/hooks/useCivicIndicators'
import { useLast48Window } from '@/hooks/useLast48Window'
import { useAnomalyBaseline } from '@/hooks/useAnomalyBaseline'
import { LAST48_DATASETS, type DatasetId } from '@/types/last48'
import {
  anomalyToWireItem,
  tickerToWireItem,
  rankWire,
  type WireItem,
} from '@/lib/pulse/pulsePhrase'
// ONE definition of "fresh enough to trust a quiet reading", shared with the
// choropleth. useAnomalyBaseline already drops stale-quiet anomalies before
// they reach us; the per-item flag below stays as the second gate that also
// governs prose, so the two can never disagree about the same stream.
import { FRESH_MAX_MS } from '@/lib/pulse/anomalyStats'

export interface UsePulseWireResult {
  items: WireItem[]
  isLoading: boolean
  /** Reader-facing notice when a stream's current 48h counts failed to load:
   *  it then has NO neighborhood cards, and a wire that said nothing would
   *  read as complete. null when every stream counted (or is still pending).
   *  Same fact the Last 48 anomaly map discloses in its pill. */
  notice: string | null
}

// Feed names as the Pulse legend prints them.
const STREAM_LABEL: Record<DatasetId, string> = {
  '911-realtime': '911',
  'fire-ems-dispatch': 'Fire/EMS',
  '311-cases': '311',
}

export function usePulseWire(): UsePulseWireResult {
  const window48 = useLast48Window({ datasets: LAST48_DATASETS })
  const { anomalies, missingCurrent } = useAnomalyBaseline({
    datasets: LAST48_DATASETS,
    freshness: window48.freshness,
  })
  const { items: tickerItems, isLoading: tickerLoading } = useCivicIndicators()

  const items = useMemo(() => {
    const now = Date.now()
    const wire: WireItem[] = []

    // Neighborhood volume anomalies — the rich count-vs-typical items.
    for (const a of anomalies) {
      if (a.datasetId === 'combined') continue
      const fresh = window48.freshness[a.datasetId]
      const freshnessOk = fresh?.eventLagMs != null && fresh.eventLagMs < FRESH_MAX_MS
      const item = anomalyToWireItem(a, { freshnessOk, computedAt: now })
      if (item) wire.push(item)
    }

    // Citywide signals from the indicator engine (already freshness-gated there).
    for (const t of tickerItems) {
      const item = tickerToWireItem(t)
      if (item) wire.push(item)
    }

    // One row per id (anomaly ids are unique per neighborhood×stream; this also
    // guards against an indicator and an anomaly colliding on id).
    const byId = new Map<string, WireItem>()
    for (const w of wire) {
      const existing = byId.get(w.id)
      if (!existing || w.rankScore > existing.rankScore) byId.set(w.id, w)
    }
    return rankWire([...byId.values()])
  }, [anomalies, tickerItems, window48.freshness])

  const notice = useMemo(() => {
    if (missingCurrent.length === 0) return null
    const names = missingCurrent.map((id) => STREAM_LABEL[id]).join(' and ')
    const one = missingCurrent.length === 1
    return `${names} neighborhood signals unavailable — ${one ? 'its' : 'their'} current counts didn’t load, so ${one ? 'that stream has' : 'those streams have'} no cards on this wire.`
  }, [missingCurrent])

  return { items, isLoading: window48.isLoading || tickerLoading, notice }
}
